#include "mpu6050.h"
#include "mpu6050.c"

static unsigned int read_calls;
static uint8_t read_address;
static uint16_t read_length;
static bool read_result;
static uint8_t read_payload[6];

static bool test_read_callback(uint8_t address, uint8_t reg, uint8_t *bytes, uint16_t length)
{
    (void)reg;
    read_calls++;
    read_address = address;
    read_length = length;
    if (read_result && (bytes != NULL) && (length >= sizeof(read_payload)))
    {
        memcpy(bytes, read_payload, sizeof(read_payload));
    }
    return read_result;
}

