void test_mpu6050_05(void)
{
    mpu6050_io_t io = {test_read_callback, NULL, 0x68U};
    mpu6050_sample_t sample = {0.0f, 0.0f, 0.0f};

    read_result = true;
    read_payload[0] = 0x7FU;
    read_payload[1] = 0xFFU; /* 32767: below the signed conversion boundary. */
    read_payload[2] = 0x80U;
    read_payload[3] = 0x00U; /* 32768: at the signed conversion boundary. */
    read_payload[4] = 0xFFU;
    read_payload[5] = 0xFFU; /* -1 after signed conversion. */

    TEST_ASSERT_TRUE(mpu6050_read(&io, &sample));
    TEST_ASSERT_EQUAL_UINT(1U, read_calls);
    TEST_ASSERT_EQUAL_UINT8(0x68U, read_address);
    TEST_ASSERT_EQUAL_UINT(6U, read_length);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, 32767.0f / 8192.0f, sample.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, -4.0f, sample.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, -1.0f / 8192.0f, sample.z_g);
}
